local B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local DEC = {}
for i = 1, #B64 do DEC[string.byte(B64, i)] = i - 1 end
-- the RGBA bytes as a buffer (for EditableImage:WritePixelsBuffer)
function Icon.pixels()
	local s = Icon.DATA
	local out = buffer.create(Icon.W * Icon.H * 4)
	local o = 0
	for i = 1, #s, 4 do
		local a, b, c, d = DEC[string.byte(s, i)], DEC[string.byte(s, i + 1)], DEC[string.byte(s, i + 2)], DEC[string.byte(s, i + 3)]
		local n = bit32.bor(bit32.lshift(a, 18), bit32.lshift(b, 12), bit32.lshift(c or 0, 6), d or 0)
		if o < buffer.len(out) then buffer.writeu8(out, o, bit32.band(bit32.rshift(n, 16), 255)) o += 1 end
		if c and o < buffer.len(out) then buffer.writeu8(out, o, bit32.band(bit32.rshift(n, 8), 255)) o += 1 end
		if d and o < buffer.len(out) then buffer.writeu8(out, o, bit32.band(n, 255)) o += 1 end
	end
	return out
end
-- an EditableImage with the logo (nil if this Studio can't make one)
function Icon.image(AssetService)
	local ok, img = pcall(function() return AssetService:CreateEditableImage({ Size = Vector2.new(Icon.W, Icon.H) }) end)
	if not ok or not img then return nil end
	local ok2 = pcall(function() img:WritePixelsBuffer(Vector2.zero, Vector2.new(Icon.W, Icon.H), Icon.pixels()) end)
	if not ok2 then pcall(function() img:Destroy() end) return nil end
	return img
end
return Icon
